import { validate, ValidationResult } from '../src/validator';
import { filterLargeList, normalizeScores } from '../src/processor';
import { runPipeline, PipelineState } from '../src/pipeline';

// --- Tests for validator.ts ---
async function testValidator() {
  console.log("--- Running Validator Tests ---");

  // Test 1: Valid object
  const schema1 = { required: ['a', 'b'] };
  const data1 = { a: 1, b: 'test' };
  let result1 = validate(data1, schema1);
  console.assert(result1.valid === true, "Test 1 Failed: Valid object should pass");

  // Test 2: Missing required field
  const schema2 = { required: ['a', 'c'] };
  const data2 = { a: 1, b: 'test' };
  let result2 = validate(data2, schema2);
  console.assert(result2.valid === false && result2.errors.includes("Missing required field: c"), "Test 2 Failed: Missing field 'c' should fail");

  // Test 3: Input is null
  const schema3 = { required: ['a'] };
  let result3 = validate(null, schema3);
  console.assert(result3.valid === false && result3.errors[0] === "Input must be an object", "Test 3 Failed: Null input should fail");

  // Test 4: Falsy but valid values (BUG FIX verification)
  const schema4 = { required: ['zero', 'empty', 'falsey'] };
  const data4 = { zero: 0, empty: "", falsey: false };
  let result4 = validate(data4, schema4);
  console.assert(result4.valid === true, "Test 4 Failed: Falsy values (0, '', false) should be considered valid if present");

  console.log("Validator Tests Complete.");
}

// --- Tests for processor.ts ---
async function testProcessor() {
  console.log("\n--- Running Processor Tests ---");

  // Test 1: Small list (length < 10) - should return original list
  const smallList = [1, 2, 3];
  let result1 = filterLargeList(smallList, () => true);
  console.assert(result1.length === 3 && result1.every((item, index) => item === smallList[index]), "Test 1 Failed: Small list should return original list");

  // Test 2: List of size 10 - should filter (BUG FIX verification: >= 10)
  const list10 = Array(10).fill(1);
  let result2 = filterLargeList(list10, () => true);
  console.assert(result2.length === 10, "Test 2 Failed: List of size 10 should be filtered");

  // Test 3: List of size 11 - should filter
  const list11 = Array(11).fill(1);
  let result3 = filterLargeList(list11, () => true);
  console.assert(result3.length === 11, "Test 3 Failed: List of size 11 should be filtered");

  // Test 4: Normalization (Max score is 10)
  const scores4 = [2, 5, 10];
  let result4 = normalizeScores(scores4);
  console.assert(result4.length === 3 && Math.abs(result4[0] - 0.2) < 1e-9 && Math.abs(result4[1] - 0.5) < 1e-9 && Math.abs(result4[2] - 1.0) < 1e-9, "Test 4 Failed: Normalization failed");

